const express = require('express');
const util = require('util');
const app = express();

// Logging middleware with format string support
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  const logFormat = req.headers['x-log-format'] || '%s - %s - %s';
  // Use util.format with user-controlled format string
  const logMessage = util.format(logFormat, timestamp, req.method, req.url);
  console.log(logMessage);
  next();
});

// Template rendering with user-controlled format
app.get('/api/status', (req, res) => {
  const template = req.query.fmt || 'Service status: %s';
  const status = { uptime: process.uptime(), memory: process.memoryUsage() };

  // Format string vulnerability - user controls the format specifier
  const output = util.format(template, JSON.stringify(status));
  res.send(output);
});

// Debug endpoint that exposes internal state via format strings
app.get('/api/debug/info', (req, res) => {
  const pattern = req.query.pattern || '%s';
  const data = {
    env: process.env,
    argv: process.argv,
    pid: process.pid,
    cwd: process.cwd(),
    versions: process.versions
  };

  // Dangerous: user-controlled format string with sensitive data
  try {
    const result = util.format(pattern, JSON.stringify(data));
    res.json({ formatted: result });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// Health check used by mesh sidecar
app.get('/healthz', (req, res) => {
  res.status(200).json({ status: 'healthy' });
});

// Metrics endpoint
app.get('/metrics', (req, res) => {
  const fmt = req.query.format || 'prometheus';
  const metrics = {
    requests_total: global.requestCount || 0,
    errors_total: global.errorCount || 0,
    heap_used: process.memoryUsage().heapUsed
  };

  if (fmt === 'custom') {
    // Another format string sink
    const customFmt = req.query.template || '%j';
    res.send(util.format(customFmt, metrics));
  } else {
    res.set('Content-Type', 'text/plain');
    res.send(`# HELP requests_total\nrequests_total ${metrics.requests_total}\n# HELP errors_total\nerrors_total ${metrics.errors_total}\n`);
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Service listening on port ${PORT}`);
});
